async function main(): Promise<void> {
    const events: string[] = [];
    setTimeout(() => {
        events.push("timer-1");
        Promise.resolve().then(() => {
            events.push("promise");
        });
    }, 0);
    setTimeout(() => {
        events.push("timer-2");
    }, 0);
    await new Promise<void>((resolve) => setTimeout(resolve, 20));
    console.log(events.join(","));
}
